def default_groups(apps, schema_editor):
    """Each company's pay cycle setting becomes its default pay group ("Everyone else"). Its pay day stays the company's
    "salary paid on" day (a cycle's empty pay day means that one)."""
    Company = apps.get_model("payroll", "Company")
    PolicyVersion = apps.get_model("payroll", "PolicyVersion")
    PayGroup = apps.get_model("payroll", "PayGroup")
    PayGroupCycle = apps.get_model("payroll", "PayGroupCycle")
    for company in Company.objects.all():
        group, created = PayGroup.objects.get_or_create(company=company, code="default",
                                                        defaults={"name": "Everyone else", "is_default": True})
        if not created:
            continue
        PayGroupCycle.objects.create(group=group, effective_from=date(2000, 1, 1), mode="calendar", start_day=1,
                                     pay_day=None, note="Calendar month (before any pay cycle was set)")
        for v in PolicyVersion.objects.filter(company=company, key="pay_cycle").order_by("effective_from", "id"):
            start = v.effective_from if v.effective_from.day == 1 else date(
                v.effective_from.year + (v.effective_from.month == 12), v.effective_from.month % 12 + 1, 1)
            mode = v.payload.get("mode", "calendar")
            PayGroupCycle.objects.create(group=group, effective_from=start, mode=mode,
                                         start_day=1 if mode == "calendar" else int(v.payload.get("start_day") or 1),
                                         pay_day=None, note=v.note or "From the pay cycle setting")


